using System;using System.Collections;using System.Collections.Generic;using System.Linq;
using Mirror;using MultiFPS;using MultiFPS.Gameplay;using MultiFPS.Gameplay.RiftCombat;using MultiFPS.UI;using ROM.UI.Gameplay;using ROM.UI.Sprint01;
using UnityEngine;using UnityEngine.UI;using UnityEngine.InputSystem;using UnityEngine.EventSystems;
namespace ROM.Tutorial.Crilium {
// Five-second in-engine event. Per-run state only; no profile/progression writes.
[DefaultExecutionOrder(-250)]public sealed class CriliumRiftFall:MonoBehaviour {
 public Transform Fragment,ImpactPoint,FlightStart,Portal;public GameObject ImpactEffect;public LineRenderer Trail;public float FlightSeconds=3.2f,AfterImpactSeconds=1.8f;
 public bool HasFallen{get;private set;}public bool Playing{get;private set;}public bool Discovered{get;private set;}public int Plays{get;private set;}
 public bool ControlsReleased=>!Playing&&!ownsCursor;public event Action Completed;
 Camera camera;RiftThirdPersonCamera orbit;Behaviour gameplayCamera;RiftMMOController input;CharacterInstance actor;PlayerInstance player;
 Vector3 oldPosition;Quaternion oldRotation;float oldFov,oldNear,oldYaw,oldPitch,oldDistance;bool oldOrbitEnabled,oldGameplayEnabled,ownsCursor,skip;int openingHealth;double openingCombat;Coroutine routine;
 Canvas overlay;Text caption;GameObject oldSelection;readonly List<Hidden> hidden=new List<Hidden>();
 struct Hidden{public CanvasGroup Group;public float Alpha;public bool Blocks,Interactable;public bool Created;}
 void Start(){ResetWorld();}
 void Update(){if(Playing){if((Keyboard.current!=null&&Keyboard.current.escapeKey.wasPressedThisFrame)||RiftControls.Pressed("Pause")){RiftControls.EscapeConsumedFrame=Time.frameCount;skip=true;}return;}if(HasFallen&&!Discovered&&ClientFrontend.OwnedCharacterInstance&&ImpactPoint&&Vector3.Distance(ClientFrontend.OwnedCharacterInstance.transform.position,ImpactPoint.position)<8){Discovered=true;RiftVillageUI.Notify("El fragmento abrió una grieta. Acercate para cruzar.");}}
 public bool TryPlay(){if(!NetworkServer.active||!CriliumSession.Active||Playing||HasFallen||!isActiveAndEnabled)return false;player=ClientFrontend.ClientPlayerInstance;actor=player?player.MyCharacter:null;var combat=player?player.GetComponent<AbilityController>():null;
  if(RiftControls.TextEntryFocused||ClientFrontend.Pause||UIPauseMenu._instance&&UIPauseMenu._instance.InterfaceShowing)return false;
  if(!actor||actor.Health.CurrentHealth<=0||!combat||combat.Casting>=0||NetworkTime.time-player.LastCombatAt<2||RiftVillageUI.Instance&&RiftVillageUI.Instance.TalkingTo)return false;
  camera=MultiFPS.GameplayCamera._instance?MultiFPS.GameplayCamera._instance.GetComponent<Camera>():null;if(!camera)return false;orbit=camera.GetComponent<RiftThirdPersonCamera>();gameplayCamera=MultiFPS.GameplayCamera._instance;input=RiftMMOController.Instance;
  oldPosition=camera.transform.position;oldRotation=camera.transform.rotation;oldFov=camera.fieldOfView;oldNear=camera.nearClipPlane;oldOrbitEnabled=orbit&&orbit.enabled;oldGameplayEnabled=gameplayCamera&&gameplayCamera.enabled;if(input){oldYaw=input.CameraYaw;oldPitch=input.CameraPitch;oldDistance=input.CameraDistance;}
  openingHealth=actor.Health.CurrentHealth;openingCombat=player.LastCombatAt;oldSelection=EventSystem.current?EventSystem.current.currentSelectedGameObject:null;Playing=true;skip=false;Plays++;if(orbit)orbit.enabled=false;if(gameplayCamera)gameplayCamera.enabled=false;actor.Input.Movement=Vector2.zero;UICursorManager.RequestCursor(gameObject);ownsCursor=true;BuildOverlay();HideHud();routine=StartCoroutine(Sequence());return true;
 }
 IEnumerator Sequence(){float elapsed=0;try{while(elapsed<FlightSeconds+AfterImpactSeconds&&!skip){if(!actor||actor.Health.CurrentHealth<=0||actor.Health.CurrentHealth<openingHealth||player.LastCombatAt>openingCombat+.0001)break;float p=Mathf.Clamp01(elapsed/FlightSeconds);Preview(p);if(camera){var a=ImpactPoint.position+new Vector3(16,10,-24);var b=ImpactPoint.position+new Vector3(8,6,-14);camera.transform.position=Vector3.Lerp(a,b,Mathf.SmoothStep(0,1,Mathf.Clamp01(elapsed/(FlightSeconds+AfterImpactSeconds))));Vector3 target=p<1?Fragment.position:ImpactPoint.position+Vector3.up*1.2f;camera.transform.rotation=Quaternion.LookRotation(target-camera.transform.position);camera.fieldOfView=58;camera.nearClipPlane=.2f;}if(caption)caption.text=p<1?"Algo atraviesa el cielo de Crelium…":"El fragmento del Rift ha caído. Investigá el impacto.";elapsed+=Time.unscaledDeltaTime;yield return null;}CompleteWorld();}finally{Restore();}routine=null;Completed?.Invoke();}
 public void Skip(){if(!Playing)return;skip=true;RiftControls.EscapeConsumedFrame=Time.frameCount;}
 public void Preview(float progress){if(!Fragment||!FlightStart||!ImpactPoint)return;progress=Mathf.Clamp01(progress);Fragment.gameObject.SetActive(true);Fragment.position=Position(progress);Fragment.rotation=Quaternion.Euler(progress*320,progress*190,progress*70);if(Trail){Trail.gameObject.SetActive(progress<1);for(int i=0;i<Trail.positionCount;i++){float t=Mathf.Clamp01(progress-.18f+.18f*i/(Trail.positionCount-1));Trail.SetPosition(i,Position(t));}}bool hit=progress>=1;if(ImpactEffect&&ImpactEffect.activeSelf!=hit){ImpactEffect.SetActive(hit);if(hit)foreach(var ps in ImpactEffect.GetComponentsInChildren<ParticleSystem>())ps.Play();}if(Portal)Portal.gameObject.SetActive(hit);}
 Vector3 Position(float p)=>Vector3.Lerp(FlightStart.position,ImpactPoint.position+Vector3.up*.7f,p)+Vector3.up*Mathf.Sin(p*Mathf.PI)*14;
 public void RestoreCompletedWorld(){if(!CriliumSession.Active||Playing)return;Preview(1);HasFallen=true;}
 public void ResetWorld(){if(Fragment)Fragment.gameObject.SetActive(false);if(Trail)Trail.gameObject.SetActive(false);if(ImpactEffect)ImpactEffect.SetActive(false);if(Portal)Portal.gameObject.SetActive(false);}
 void CompleteWorld(){Preview(1);HasFallen=true;}
 void Hide(Transform root){if(!root)return;var group=root.GetComponent<CanvasGroup>();bool made=!group;if(made)group=root.gameObject.AddComponent<CanvasGroup>();hidden.Add(new Hidden{Group=group,Alpha=group.alpha,Blocks=group.blocksRaycasts,Interactable=group.interactable,Created=made});group.alpha=0;group.blocksRaycasts=group.interactable=false;}
 void HideHud(){var hud=UnityEngine.Object.FindFirstObjectByType<RiftGameplayHUD>();if(hud)Hide(hud.transform);var field=UnityEngine.Object.FindFirstObjectByType<RiftFieldUI>();if(field){field.SetMap(false);Hide(field.transform);}var director=GetComponent<CriliumDirector>();if(director){var guidance=director.transform.Find("Crilium guidance");if(guidance)Hide(guidance);}}
 void BuildOverlay(){var root=new GameObject("Crelium fall cinematic overlay",typeof(RectTransform),typeof(Canvas),typeof(CanvasScaler),typeof(GraphicRaycaster));root.transform.SetParent(transform,false);overlay=root.GetComponent<Canvas>();overlay.renderMode=RenderMode.ScreenSpaceOverlay;overlay.sortingOrder=500;var scale=root.GetComponent<CanvasScaler>();scale.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;scale.referenceResolution=new Vector2(1920,1080);scale.matchWidthOrHeight=1;
  foreach(bool top in new[]{false,true}){var bar=Rect(root.transform,"Cinematic letterbox",new Vector2(.5f,top?1:0),new Vector2(0,top?-40:40),new Vector2(3000,80)).gameObject.AddComponent<Image>();bar.color=new Color(0,0,0,.74f);bar.raycastTarget=false;}
  caption=Rect(root.transform,"Cinematic caption",new Vector2(.5f,0),new Vector2(0,40),new Vector2(1020,60)).gameObject.AddComponent<Text>();caption.font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");caption.fontSize=23;caption.alignment=TextAnchor.MiddleCenter;caption.color=new Color(.94f,.91f,1);caption.raycastTarget=false;caption.supportRichText=false;
  var buttonRoot=Rect(root.transform,"Skip cinematic",new Vector2(1,0),new Vector2(-130,115),new Vector2(220,42));var img=buttonRoot.gameObject.AddComponent<Image>();img.color=new Color(.1f,.055f,.18f,.9f);var button=buttonRoot.gameObject.AddComponent<Button>();button.targetGraphic=img;button.onClick.AddListener(Skip);var label=Rect(buttonRoot,"Label",new Vector2(.5f,.5f),Vector2.zero,new Vector2(210,40)).gameObject.AddComponent<Text>();label.font=caption.font;label.fontSize=17;label.alignment=TextAnchor.MiddleCenter;label.color=caption.color;label.text="Omitir ["+RiftControls.ActionLabel("Pause")+"]";label.raycastTarget=false;if(EventSystem.current)EventSystem.current.SetSelectedGameObject(button.gameObject);
 }
 RectTransform Rect(Transform parent,string name,Vector2 anchor,Vector2 at,Vector2 size){var r=new GameObject(name,typeof(RectTransform)).GetComponent<RectTransform>();r.SetParent(parent,false);r.anchorMin=r.anchorMax=anchor;r.sizeDelta=size;r.anchoredPosition=at;return r;}
 void Restore(){if(camera){camera.transform.SetPositionAndRotation(oldPosition,oldRotation);camera.fieldOfView=oldFov;camera.nearClipPlane=oldNear;}if(input){input.CameraYaw=oldYaw;input.CameraPitch=oldPitch;input.CameraDistance=oldDistance;}if(orbit)orbit.enabled=oldOrbitEnabled;if(gameplayCamera)gameplayCamera.enabled=oldGameplayEnabled;
  foreach(var item in hidden)if(item.Group){item.Group.alpha=item.Alpha;item.Group.blocksRaycasts=item.Blocks;item.Group.interactable=item.Interactable;if(item.Created)Destroy(item.Group);}hidden.Clear();if(overlay)Destroy(overlay.gameObject);overlay=null;if(ownsCursor){if(gameObject.scene.isLoaded)UICursorManager.ReleaseCursor(gameObject);ownsCursor=false;}Playing=false;if(EventSystem.current)EventSystem.current.SetSelectedGameObject(oldSelection&&oldSelection.activeInHierarchy?oldSelection:null);if(actor)actor.Input.Movement=Vector2.zero;}
 void OnDisable(){if(routine!=null){StopCoroutine(routine);routine=null;}if(Playing||ownsCursor)Restore();if(!HasFallen)ResetWorld();}
#if UNITY_EDITOR
 public void ResetDiagnosticSequence(){if(Playing)return;HasFallen=Discovered=false;ResetWorld();}
#endif
}
}
